// Copies shared/quicklook/quicklook.js into quicklook.g.js as an ES module, so the package carries
// its own copy and installs no global.
//
// Run from the package directory:
//   npm run build               regenerate after changing quicklook.js
//   node tool/embed.js --check  exit 1 if the generated file is out of date
import { existsSync, readFileSync, writeFileSync } from "node:fs";
import { fileURLToPath } from "node:url";

export const source = new URL("../../../shared/quicklook/quicklook.js", import.meta.url);
export const target = new URL("../quicklook.g.js", import.meta.url);

// quicklook.js exports create() through module.exports when it finds one, instead of installing
// window.ArcsiteQuickLook; the wrapper hands it a local one.
export function generate(js) {
  return (
    "// GENERATED by tool/embed.js from shared/quicklook/quicklook.js. Do not edit.\n" +
    "\n" +
    "export const { create } = (function (module) {\n" +
    js +
    "return module.exports;\n" +
    "})({ exports: {} });\n"
  );
}

function main(args) {
  const expected = generate(readFileSync(source, "utf8"));
  if (args.includes("--check")) {
    if (!existsSync(target) || readFileSync(target, "utf8") !== expected) {
      console.error("quicklook.g.js is out of date: run npm run build");
      process.exit(1);
    }
    return;
  }
  writeFileSync(target, expected);
  console.log("Wrote quicklook.g.js");
}

if (process.argv[1] === fileURLToPath(import.meta.url)) main(process.argv.slice(2));
